// HasClipping applies the HasEdge predicate on the "clipping" edge.
func HasClipping() predicate.ClippingClip {
	return predicate.ClippingClip(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ClippingTable, ClippingColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasClippingWith applies the HasEdge predicate on the "clipping" edge with a given conditions (other predicates).
func HasClippingWith(preds ...predicate.Clipping) predicate.ClippingClip {
	return predicate.ClippingClip(func(s *sql.Selector) {
		step := newClippingStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ClippingClip) predicate.ClippingClip {
	return predicate.ClippingClip(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ClippingClip) predicate.ClippingClip {
	return predicate.ClippingClip(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ClippingClip) predicate.ClippingClip {
	return predicate.ClippingClip(sql.NotPredicates(p))
}
